import{_ as e,c as r,o as i,af as n}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"61、【中孚】 兌下巽上","description":"溫公易說 - 61、【中孚】 兌下巽上","frontmatter":{"title":"61、【中孚】 兌下巽上","description":"溫公易說 - 61、【中孚】 兌下巽上"},"headers":[],"relativePath":"classics/wengong/062.md","filePath":"classics/wengong/062.md"}'),l={name:"classics/wengong/062.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_61、【中孚】-兌下巽上" tabindex="-1">61、【中孚】 兌下巽上 <a class="header-anchor" href="#_61、【中孚】-兌下巽上" aria-label="Permalink to “61、【中孚】 兌下巽上”">​</a></h1><h3 id="彖曰-中孚-柔在內而剛得中-說而巽-孚乃化邦也。豚魚吉-信及豚魚也。利涉大川-乘木舟虛也。中孚以利貞-乃應乎天也。" tabindex="-1">彖曰：中孚，柔在內而剛得中，說而巽，孚乃化邦也。豚魚吉，信及豚魚也。利涉大川，乘木舟虛也。中孚以利貞，乃應乎天也。 <a class="header-anchor" href="#彖曰-中孚-柔在內而剛得中-說而巽-孚乃化邦也。豚魚吉-信及豚魚也。利涉大川-乘木舟虛也。中孚以利貞-乃應乎天也。" aria-label="Permalink to “彖曰：中孚，柔在內而剛得中，說而巽，孚乃化邦也。豚魚吉，信及豚魚也。利涉大川，乘木舟虛也。中孚以利貞，乃應乎天也。”">​</a></h3><p>中孚者，發於中而孚於人也。豚魚，幽賤無知之物，茍飼以時，則應聲而集，而況於人乎？至誠以涉險，如乘虛舟，物莫之害，故曰利涉大川，乘木舟虛也。</p><h3 id="象曰-澤上有風-中孚。君子以議獄緩死。" tabindex="-1">象曰：澤上有風，中孚。君子以議獄緩死。 <a class="header-anchor" href="#象曰-澤上有風-中孚。君子以議獄緩死。" aria-label="Permalink to “象曰：澤上有風，中孚。君子以議獄緩死。”">​</a></h3><h3 id="初九-虞吉-有他不燕-象曰-初九虞吉-志未變也。" tabindex="-1">初九：虞吉，有他不燕 象曰：初九虞吉，志未變也。 <a class="header-anchor" href="#初九-虞吉-有他不燕-象曰-初九虞吉-志未變也。" aria-label="Permalink to “初九：虞吉，有他不燕 象曰：初九虞吉，志未變也。”">​</a></h3><h3 id="九二-鳴鶴在陰-其子和之。我有好爵-吾與爾靡之-象曰-其子和之-中心願也。" tabindex="-1">九二：鳴鶴在陰，其子和之。我有好爵，吾與爾靡之 象曰：其子和之，中心願也。 <a class="header-anchor" href="#九二-鳴鶴在陰-其子和之。我有好爵-吾與爾靡之-象曰-其子和之-中心願也。" aria-label="Permalink to “九二：鳴鶴在陰，其子和之。我有好爵，吾與爾靡之 象曰：其子和之，中心願也。”">​</a></h3><p>鳴鶴在陰，其子和之，言至誠以待物，無遠不應。</p><h3 id="六三-得敵-或鼓或罷-或泣或歌-象曰-或鼓或罷-位不當也。" tabindex="-1">六三：得敵，或鼓或罷，或泣或歌 象曰：或鼓或罷，位不當也。 <a class="header-anchor" href="#六三-得敵-或鼓或罷-或泣或歌-象曰-或鼓或罷-位不當也。" aria-label="Permalink to “六三：得敵，或鼓或罷，或泣或歌 象曰：或鼓或罷，位不當也。”">​</a></h3><h3 id="六四-月幾望-馬匹亡-無咎-象曰-馬匹亡-絕類上也。" tabindex="-1">六四：月幾望，馬匹亡，無咎 象曰：馬匹亡，絕類上也。 <a class="header-anchor" href="#六四-月幾望-馬匹亡-無咎-象曰-馬匹亡-絕類上也。" aria-label="Permalink to “六四：月幾望，馬匹亡，無咎 象曰：馬匹亡，絕類上也。”">​</a></h3><h3 id="九五-有孚-攣如-無咎-象曰-有孚攣如-位正當也。" tabindex="-1">九五：有孚，攣如，無咎 象曰：有孚攣如，位正當也。 <a class="header-anchor" href="#九五-有孚-攣如-無咎-象曰-有孚攣如-位正當也。" aria-label="Permalink to “九五：有孚，攣如，無咎 象曰：有孚攣如，位正當也。”">​</a></h3><h3 id="上九-翰音登於天-貞兇-象曰-翰音登於天-何可長也。" tabindex="-1">上九：翰音登於天，貞兇 象曰：翰音登於天，何可長也。 <a class="header-anchor" href="#上九-翰音登於天-貞兇-象曰-翰音登於天-何可長也。" aria-label="Permalink to “上九：翰音登於天，貞兇 象曰：翰音登於天，何可長也。”">​</a></h3>',11)])])}const f=e(l,[["render",t]]);export{b as __pageData,f as default};
